const header=document.querySelector('.site-header');
if(header)addEventListener('scroll',()=>header.classList.toggle('scrolled',scrollY>35),{passive:true});
const toggle=document.querySelector('.menu-toggle'),mobile=document.querySelector('.mobile-menu');
if(toggle){toggle.addEventListener('click',()=>{const open=!mobile.classList.contains('open');mobile.classList.toggle('open',open);document.body.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',open);mobile.setAttribute('aria-hidden',!open)});mobile.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobile.classList.remove('open');document.body.classList.remove('menu-open')}))}
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
document.querySelectorAll('.filters button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelector('.filters .active')?.classList.remove('active');btn.classList.add('active');const f=btn.dataset.filter;document.querySelectorAll('.gallery-item').forEach((item,i)=>{const hide=f!=='all'&&item.dataset.category!==f;item.style.opacity='0';setTimeout(()=>{item.classList.toggle('hiding',hide);if(!hide)requestAnimationFrame(()=>item.style.opacity='1')},160+i*18)})}));
const lightbox=document.querySelector('.lightbox');
if(lightbox){const triggers=[...document.querySelectorAll('[data-index]')];const slides=triggers.map(t=>({src:t.querySelector('img').src.replace(/w=\d+/,'w=2000'),alt:t.querySelector('img').alt,caption:t.querySelector('span')?.innerText||t.querySelector('img').alt}));let current=0,touchX=0;const show=i=>{current=(i+slides.length)%slides.length;lightbox.querySelector('img').src=slides[current].src;lightbox.querySelector('img').alt=slides[current].alt;lightbox.querySelector('figcaption').textContent=slides[current].caption};triggers.forEach((t,i)=>t.addEventListener('click',()=>{show(i);lightbox.showModal()}));lightbox.querySelector('.lb-close').onclick=()=>lightbox.close();lightbox.querySelector('.lb-prev').onclick=()=>show(current-1);lightbox.querySelector('.lb-next').onclick=()=>show(current+1);lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')show(current-1);if(e.key==='ArrowRight')show(current+1)});lightbox.addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});lightbox.addEventListener('touchend',e=>{const d=e.changedTouches[0].clientX-touchX;if(Math.abs(d)>45)show(current+(d<0?1:-1))},{passive:true})}
